[Console]::OutputEncoding=[Text.Encoding]::UTF8
try { $v=@(Get-CimInstance -Namespace 'root\CIMV2\Security\MicrosoftVolumeEncryption' -ClassName Win32_EncryptableVolume -ErrorAction Stop) } catch { $v=$null }
if($null -eq $v){
  'BITLOCKER_NICHT_ABFRAGBAR'
  try { $roh=@(manage-bde -status 2>&1) } catch { $roh=@() }
  if($roh.Count -gt 0){ 'Ausgabe von manage-bde -status:'; $roh | Select-Object -First 40 | ForEach-Object { '  '+$_ } }
  exit 0
}
if($v.Count -eq 0){ 'Keine Laufwerke gefunden, die sich verschlüsseln lassen.'; exit 0 }
$methoden=@{0='keine';1='AES 128 mit Diffuser';2='AES 256 mit Diffuser';3='AES 128';4='AES 256';5='Hardware';6='XTS-AES 128';7='XTS-AES 256'}
$verschluesselt=0
foreach($x in $v){
  $name=$x.DriveLetter; if(-not $name){ $name=$x.DeviceID }
  $schutz=(Invoke-CimMethod -InputObject $x -MethodName GetProtectionStatus).ProtectionStatus
  $konv=Invoke-CimMethod -InputObject $x -MethodName GetConversionStatus
  $sperre=(Invoke-CimMethod -InputObject $x -MethodName GetLockStatus).LockStatus
  $meth=(Invoke-CimMethod -InputObject $x -MethodName GetEncryptionMethod).EncryptionMethod
  $kennwort=@((Invoke-CimMethod -InputObject $x -MethodName GetKeyProtectors -Arguments @{KeyProtectorType=3}).VolumeKeyProtectorID).Count
  $art=$methoden[[int]$meth]; if(-not $art){ $art='unbekannt' }
  switch([int]$konv.ConversionStatus){
    0 { 'Laufwerk '+$name+' nicht verschlüsselt.' }
    2 { $verschluesselt++; 'Laufwerk '+$name+' wird gerade verschlüsselt ('+$konv.EncryptionPercentage+' %).' }
    3 { 'Laufwerk '+$name+' wird gerade entschlüsselt ('+$konv.EncryptionPercentage+' %).' }
    4 { $verschluesselt++; 'Laufwerk '+$name+' Verschlüsselung angehalten ('+$konv.EncryptionPercentage+' %).' }
    5 { 'Laufwerk '+$name+' Entschlüsselung angehalten ('+$konv.EncryptionPercentage+' %).' }
    default {
      $verschluesselt++
      if([int]$sperre -eq 1){ 'Laufwerk '+$name+' verschlüsselt und gesperrt (Methode '+$art+'): ohne Schlüssel nicht lesbar.' }
      elseif([int]$schutz -eq 1){ 'Laufwerk '+$name+' verschlüsselt, Schutz aktiv (Methode '+$art+').' }
      else { 'Laufwerk '+$name+' verschlüsselt, Schutz ausgesetzt (Methode '+$art+'): Windows hat BitLocker vorübergehend angehalten, z. B. für ein Update.' }
      if($kennwort -eq 0 -and [int]$konv.ConversionStatus -eq 1){ 'Laufwerk '+$name+' kein Wiederherstellungskennwort vorhanden: Bei Problemen sind die Daten ohne Schlüssel verloren.' }
    }
  }
}
if($verschluesselt -gt 0){ 'Hinweis: Den Wiederherstellungsschlüssel (48 Ziffern) bereithalten: im Microsoft-Konto unter account.microsoft.com/devices/recoverykey oder auf einem Ausdruck.' }
